BEGIN;

INSERT INTO permission_catalog(permission_code,domain,risk_class,sod_class) VALUES
 ('REAL_ESTATE.UNIT_TRANSFER.REVERSE','REAL_ESTATE','CRITICAL','UNIT_TRANSFER_REVERSAL')
ON CONFLICT(permission_code) DO UPDATE SET active=true,domain=EXCLUDED.domain,risk_class=EXCLUDED.risk_class,
 sod_class=EXCLUDED.sod_class,version=permission_catalog.version+1,effective_to=NULL;
INSERT INTO runtime_human_permission_authority(permission_code,authority_class) VALUES
 ('REAL_ESTATE.UNIT_TRANSFER.REVERSE','REVERSAL')
ON CONFLICT(permission_code) DO UPDATE SET authority_class=EXCLUDED.authority_class;

-- The paired Unit Transfer Post extension below is the only OPEN-item writer in
-- this migration.  Existing Posted history is not backfilled because its intervening
-- settlement history cannot be proven; its reversal therefore remains fail closed.
CREATE TABLE unit_transfer_ic_open_item(
 unit_transfer_ic_open_item_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 tenant_id uuid NOT NULL,unit_transfer_pair_id uuid NOT NULL,entity_id uuid NOT NULL,counterparty_entity_id uuid NOT NULL,journal_entry_id uuid NOT NULL,ledger_line_id uuid NOT NULL,
 direction text NOT NULL CHECK(direction IN('DUE_FROM','DUE_TO')),currency char(3) NOT NULL CHECK(currency~'^[A-Z]{3}$'),
 account_code text NOT NULL,counterparty_member_ref text NOT NULL,
 original_amount numeric(20,4) NOT NULL CHECK(original_amount>0),remaining_amount numeric(20,4) NOT NULL CHECK(remaining_amount>=0 AND remaining_amount<=original_amount),
 status text NOT NULL CHECK(status IN('OPEN','SETTLED')),version bigint NOT NULL DEFAULT 0 CHECK(version>=0),
 settlement_authority_ref text NOT NULL CHECK(length(btrim(settlement_authority_ref)) BETWEEN 8 AND 512),
 evidence_hash text NOT NULL CHECK(evidence_hash~'^sha256:[0-9a-f]{64}$'),settled_by_journal_entry_id uuid,settlement_evidence_hash text CHECK(settlement_evidence_hash~'^sha256:[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK((status='OPEN' AND remaining_amount>0 AND settled_by_journal_entry_id IS NULL AND settlement_evidence_hash IS NULL) OR(status='SETTLED' AND remaining_amount=0 AND settled_by_journal_entry_id IS NOT NULL AND settlement_evidence_hash IS NOT NULL)),
 UNIQUE(tenant_id,unit_transfer_pair_id,entity_id,direction),UNIQUE(tenant_id,unit_transfer_ic_open_item_id),
 FOREIGN KEY(tenant_id,unit_transfer_pair_id) REFERENCES unit_transfer_pair(tenant_id,unit_transfer_pair_id),
 FOREIGN KEY(tenant_id,entity_id) REFERENCES entity(tenant_id,entity_id),FOREIGN KEY(tenant_id,counterparty_entity_id) REFERENCES entity(tenant_id,entity_id),
 FOREIGN KEY(tenant_id,entity_id,journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,journal_entry_id),FOREIGN KEY(tenant_id,entity_id,ledger_line_id) REFERENCES ledger_line(tenant_id,entity_id,ledger_line_id),FOREIGN KEY(tenant_id,entity_id,settled_by_journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,journal_entry_id)
);
ALTER TABLE unit_transfer_ic_open_item ENABLE ROW LEVEL SECURITY;
CREATE POLICY unit_transfer_ic_open_item_scope ON unit_transfer_ic_open_item USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id) AND refs_entity_allowed(counterparty_entity_id));
REVOKE ALL ON unit_transfer_ic_open_item FROM PUBLIC,refs_app;

CREATE TABLE unit_transfer_reversal_pair(
 unit_transfer_reversal_pair_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,
 original_unit_transfer_pair_id uuid NOT NULL,unit_control_id uuid NOT NULL,source_entity_id uuid NOT NULL,target_entity_id uuid NOT NULL,
 source_period_id uuid NOT NULL,target_period_id uuid NOT NULL,reversal_date date NOT NULL,currency char(3) NOT NULL CHECK(currency~'^[A-Z]{3}$'),
 source_original_journal_entry_id uuid NOT NULL,target_original_journal_entry_id uuid NOT NULL,
 source_reversal_journal_entry_id uuid NOT NULL,target_reversal_journal_entry_id uuid NOT NULL,
 source_ic_open_item_id uuid NOT NULL,target_ic_open_item_id uuid NOT NULL,expected_source_ic_version bigint NOT NULL CHECK(expected_source_ic_version>=0),expected_target_ic_version bigint NOT NULL CHECK(expected_target_ic_version>=0),
 expected_unit_version bigint NOT NULL CHECK(expected_unit_version>=0),expected_prior_reversal_id uuid,expected_original_pair_revision bigint NOT NULL CHECK(expected_original_pair_revision>=0),
 expected_source_original_revision bigint NOT NULL CHECK(expected_source_original_revision>=0),expected_target_original_revision bigint NOT NULL CHECK(expected_target_original_revision>=0),
 target_cost_ledger_line_ids uuid[] NOT NULL CHECK(cardinality(target_cost_ledger_line_ids)>0),target_cost_basis_hash text NOT NULL CHECK(target_cost_basis_hash~'^sha256:[0-9a-f]{64}$'),
 source_reversal_journal_snapshot_hash text NOT NULL CHECK(source_reversal_journal_snapshot_hash~'^sha256:[0-9a-f]{64}$'),target_reversal_journal_snapshot_hash text NOT NULL CHECK(target_reversal_journal_snapshot_hash~'^sha256:[0-9a-f]{64}$'),
 source_attachment_snapshot_hash text NOT NULL CHECK(source_attachment_snapshot_hash~'^sha256:[0-9a-f]{64}$'),target_attachment_snapshot_hash text NOT NULL CHECK(target_attachment_snapshot_hash~'^sha256:[0-9a-f]{64}$'),
 status text NOT NULL DEFAULT 'DRAFT_PAIR' CHECK(status IN('DRAFT_PAIR','PENDING_REVIEW_PAIR','PENDING_APPROVAL_PAIR','APPROVED_PAIR','POSTED_PAIR','CANCELLED_PAIR')),
 revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 8 AND 2000),evidence_hash text NOT NULL CHECK(evidence_hash~'^sha256:[0-9a-f]{64}$'),
 created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz,cancelled_by text,cancelled_at timestamptz,cancel_reason text,
 CHECK((status='POSTED_PAIR' AND completed_at IS NOT NULL AND cancelled_at IS NULL) OR(status='CANCELLED_PAIR' AND completed_at IS NULL AND cancelled_by IS NOT NULL AND cancelled_at IS NOT NULL AND length(btrim(cancel_reason)) BETWEEN 8 AND 2000) OR(status NOT IN('POSTED_PAIR','CANCELLED_PAIR') AND completed_at IS NULL AND cancelled_by IS NULL AND cancelled_at IS NULL AND cancel_reason IS NULL)),
 UNIQUE(tenant_id,unit_transfer_reversal_pair_id),UNIQUE(tenant_id,source_entity_id,source_reversal_journal_entry_id),UNIQUE(tenant_id,target_entity_id,target_reversal_journal_entry_id),
 FOREIGN KEY(tenant_id,original_unit_transfer_pair_id) REFERENCES unit_transfer_pair(tenant_id,unit_transfer_pair_id),
 FOREIGN KEY(tenant_id,unit_control_id) REFERENCES unit_transfer_unit_control(tenant_id,unit_control_id),
 FOREIGN KEY(tenant_id,source_entity_id,source_period_id,source_reversal_journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,period_id,journal_entry_id),
 FOREIGN KEY(tenant_id,target_entity_id,target_period_id,target_reversal_journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,period_id,journal_entry_id),
 FOREIGN KEY(tenant_id,source_entity_id,source_original_journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,journal_entry_id),
 FOREIGN KEY(tenant_id,target_entity_id,target_original_journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,journal_entry_id),
 FOREIGN KEY(tenant_id,source_ic_open_item_id) REFERENCES unit_transfer_ic_open_item(tenant_id,unit_transfer_ic_open_item_id),
 FOREIGN KEY(tenant_id,target_ic_open_item_id) REFERENCES unit_transfer_ic_open_item(tenant_id,unit_transfer_ic_open_item_id)
);
CREATE UNIQUE INDEX unit_transfer_reversal_one_live_original_uq ON unit_transfer_reversal_pair(tenant_id,original_unit_transfer_pair_id) WHERE status<>'CANCELLED_PAIR';
CREATE UNIQUE INDEX unit_transfer_reversal_one_open_unit_uq ON unit_transfer_reversal_pair(tenant_id,unit_control_id) WHERE status NOT IN('POSTED_PAIR','CANCELLED_PAIR');
ALTER TABLE unit_transfer_reversal_pair ENABLE ROW LEVEL SECURITY;
CREATE POLICY unit_transfer_reversal_pair_scope ON unit_transfer_reversal_pair USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(source_entity_id) AND refs_entity_allowed(target_entity_id));
REVOKE ALL ON unit_transfer_reversal_pair FROM PUBLIC,refs_app;

CREATE FUNCTION refs_guard_unit_transfer_create_against_reversal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE u unit_transfer_unit_control;
BEGIN SELECT * INTO u FROM unit_transfer_unit_control WHERE tenant_id=NEW.tenant_id AND unit_control_id=NEW.unit_control_id FOR UPDATE;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.tenant_id::text||':'||u.property_ref||':'||u.unit_ref,0));
 IF EXISTS(SELECT 1 FROM unit_transfer_reversal_pair r WHERE r.tenant_id=NEW.tenant_id AND r.unit_control_id=NEW.unit_control_id AND r.status NOT IN('POSTED_PAIR','CANCELLED_PAIR')) THEN RAISE EXCEPTION 'Unit has an active paired reversal' USING ERRCODE='40001';END IF;RETURN NEW;END;$$;
CREATE TRIGGER unit_transfer_create_reversal_race_guard BEFORE INSERT ON unit_transfer_pair FOR EACH ROW EXECUTE FUNCTION refs_guard_unit_transfer_create_against_reversal();

ALTER TABLE unit_transfer_unit_control ADD COLUMN last_transfer_reversal_id uuid;
ALTER TABLE unit_transfer_unit_control ADD CONSTRAINT unit_transfer_unit_control_last_reversal_tenant_fk FOREIGN KEY(tenant_id,last_transfer_reversal_id) REFERENCES unit_transfer_reversal_pair(tenant_id,unit_transfer_reversal_pair_id);
ALTER TABLE unit_transfer_reversal_pair ADD CONSTRAINT unit_transfer_reversal_prior_tenant_fk FOREIGN KEY(tenant_id,expected_prior_reversal_id) REFERENCES unit_transfer_reversal_pair(tenant_id,unit_transfer_reversal_pair_id);
ALTER TABLE unit_transfer_elimination_basis ADD CONSTRAINT unit_transfer_elimination_basis_tenant_id_uq UNIQUE(tenant_id,elimination_basis_id);

CREATE TABLE unit_transfer_elimination_reversal_basis(
 elimination_reversal_basis_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,unit_transfer_reversal_pair_id uuid NOT NULL UNIQUE,original_elimination_basis_id uuid NOT NULL,
 source_entity_id uuid NOT NULL,target_entity_id uuid NOT NULL,currency char(3) NOT NULL,
 original_intercompany_profit numeric(20,4) NOT NULL CHECK(original_intercompany_profit>=0),signed_elimination_amount numeric(20,4) NOT NULL CHECK(signed_elimination_amount<=0),
 source_reversal_journal_entry_id uuid NOT NULL,target_reversal_journal_entry_id uuid NOT NULL,evidence_hash text NOT NULL CHECK(evidence_hash~'^sha256:[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK(signed_elimination_amount=-original_intercompany_profit),
 FOREIGN KEY(tenant_id,unit_transfer_reversal_pair_id) REFERENCES unit_transfer_reversal_pair(tenant_id,unit_transfer_reversal_pair_id),
 FOREIGN KEY(tenant_id,original_elimination_basis_id) REFERENCES unit_transfer_elimination_basis(tenant_id,elimination_basis_id),
 FOREIGN KEY(tenant_id,source_entity_id,source_reversal_journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,journal_entry_id),
 FOREIGN KEY(tenant_id,target_entity_id,target_reversal_journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,journal_entry_id)
);
ALTER TABLE unit_transfer_elimination_reversal_basis ENABLE ROW LEVEL SECURITY;
CREATE POLICY unit_transfer_elimination_reversal_basis_scope ON unit_transfer_elimination_reversal_basis USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(source_entity_id) AND refs_entity_allowed(target_entity_id));
REVOKE ALL ON unit_transfer_elimination_reversal_basis FROM PUBLIC,refs_app;

ALTER TABLE unit_transfer_internal_gate DROP CONSTRAINT unit_transfer_internal_gate_resource_kind_check;
ALTER TABLE unit_transfer_internal_gate ADD CONSTRAINT unit_transfer_internal_gate_resource_kind_check CHECK(resource_kind IN('JOURNAL','PAIR','UNIT','HEADER','IC_OPEN_ITEM'));

CREATE FUNCTION refs_protect_unit_transfer_ic_open_item() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE gate integer;
BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Unit Transfer IC open-item evidence is retained' USING ERRCODE='55000';END IF;
 IF TG_OP='INSERT' THEN DELETE FROM unit_transfer_internal_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=NEW.tenant_id AND unit_transfer_pair_id=NEW.unit_transfer_pair_id AND resource_kind='IC_OPEN_ITEM' AND resource_id=NEW.journal_entry_id AND operation='OPEN' RETURNING 1 INTO gate;IF gate IS NULL OR NEW.status<>'OPEN' OR NEW.remaining_amount<>NEW.original_amount THEN RAISE EXCEPTION 'Unit Transfer IC open item must originate in paired Post' USING ERRCODE='55000';END IF;RETURN NEW;END IF;
 DELETE FROM unit_transfer_internal_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=NEW.tenant_id AND unit_transfer_pair_id=NEW.unit_transfer_pair_id AND resource_kind='IC_OPEN_ITEM' AND resource_id=NEW.journal_entry_id AND operation='SETTLED' RETURNING 1 INTO gate;
 IF gate IS NULL OR OLD.status<>'OPEN' OR NEW.status<>'SETTLED' OR NEW.remaining_amount<>0 OR NEW.version<>OLD.version+1 OR (NEW.tenant_id,NEW.unit_transfer_pair_id,NEW.entity_id,NEW.counterparty_entity_id,NEW.journal_entry_id,NEW.ledger_line_id,NEW.direction,NEW.currency,NEW.account_code,NEW.counterparty_member_ref,NEW.original_amount,NEW.settlement_authority_ref,NEW.evidence_hash,NEW.created_at) IS DISTINCT FROM(OLD.tenant_id,OLD.unit_transfer_pair_id,OLD.entity_id,OLD.counterparty_entity_id,OLD.journal_entry_id,OLD.ledger_line_id,OLD.direction,OLD.currency,OLD.account_code,OLD.counterparty_member_ref,OLD.original_amount,OLD.settlement_authority_ref,OLD.evidence_hash,OLD.created_at) THEN RAISE EXCEPTION 'Unit Transfer IC open item settlement is unauthorized' USING ERRCODE='55000';END IF;RETURN NEW;END;$$;
CREATE TRIGGER unit_transfer_ic_open_item_protect BEFORE INSERT OR UPDATE OR DELETE ON unit_transfer_ic_open_item FOR EACH ROW EXECUTE FUNCTION refs_protect_unit_transfer_ic_open_item();

-- Extend future paired Posts only.  Existing POSTED_PAIR rows are deliberately
-- not backfilled because their settlement history cannot be proven.
DO $unit_transfer_post_patch$DECLARE fn text;patched text;BEGIN
 fn:=pg_get_functiondef('refs_post_unit_transfer_pair(uuid,uuid,uuid,bigint,bigint,bigint,text,text)'::regprocedure);
 patched:=replace(fn,'public.refs_post_unit_transfer_pair(','public.refs_post_unit_transfer_pair_370(');
 IF patched=fn THEN RAISE EXCEPTION 'Unable to retain 370 Unit Transfer Post function' USING ERRCODE='55000';END IF;BEGIN EXECUTE patched||';'; EXCEPTION WHEN syntax_error THEN RAISE EXCEPTION 'Unit Transfer migration post backup definition is invalid' USING ERRCODE='42601'; END;
 patched:=replace(fn,$needle$ INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'UNIT',pair.unit_control_id,'TRANSFERRED');$needle$,$replacement$
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'IC_OPEN_ITEM',pair.source_journal_entry_id,'OPEN');
 INSERT INTO unit_transfer_ic_open_item(tenant_id,unit_transfer_pair_id,entity_id,counterparty_entity_id,journal_entry_id,ledger_line_id,direction,currency,account_code,counterparty_member_ref,original_amount,remaining_amount,status,settlement_authority_ref,evidence_hash)
 SELECT p_tenant,p_pair,pair.source_entity_id,pair.target_entity_id,pair.source_journal_entry_id,ll.ledger_line_id,'DUE_FROM',pair.currency,pair.source_due_from_account_code,jl.member_ref,pair.transfer_price,pair.transfer_price,'OPEN','UNIT_TRANSFER_POST:'||p_pair,refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_IC_OPEN_ITEM_V1','unit_transfer_pair_id',p_pair,'entity_id',pair.source_entity_id,'counterparty_entity_id',pair.target_entity_id,'journal_entry_id',pair.source_journal_entry_id,'ledger_line_id',ll.ledger_line_id,'direction','DUE_FROM','account_code',pair.source_due_from_account_code,'counterparty_member_ref',jl.member_ref,'currency',pair.currency,'amount',pair.transfer_price))
 FROM ledger_line ll JOIN journal_line jl ON jl.tenant_id=ll.tenant_id AND jl.entity_id=ll.entity_id AND jl.journal_line_id=ll.journal_line_id WHERE ll.tenant_id=p_tenant AND ll.entity_id=pair.source_entity_id AND ll.journal_entry_id=pair.source_journal_entry_id AND ll.posting_batch_id=(source_result->>'posting_batch_id')::uuid AND ll.account_code=pair.source_due_from_account_code AND ll.debit_amount=pair.transfer_price AND ll.credit_amount=0 AND jl.dimensions->>'counterparty_entity_id'=pair.target_entity_id::text;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'IC_OPEN_ITEM',pair.target_journal_entry_id,'OPEN');
 INSERT INTO unit_transfer_ic_open_item(tenant_id,unit_transfer_pair_id,entity_id,counterparty_entity_id,journal_entry_id,ledger_line_id,direction,currency,account_code,counterparty_member_ref,original_amount,remaining_amount,status,settlement_authority_ref,evidence_hash)
 SELECT p_tenant,p_pair,pair.target_entity_id,pair.source_entity_id,pair.target_journal_entry_id,ll.ledger_line_id,'DUE_TO',pair.currency,pair.target_due_to_account_code,jl.member_ref,pair.transfer_price,pair.transfer_price,'OPEN','UNIT_TRANSFER_POST:'||p_pair,refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_IC_OPEN_ITEM_V1','unit_transfer_pair_id',p_pair,'entity_id',pair.target_entity_id,'counterparty_entity_id',pair.source_entity_id,'journal_entry_id',pair.target_journal_entry_id,'ledger_line_id',ll.ledger_line_id,'direction','DUE_TO','account_code',pair.target_due_to_account_code,'counterparty_member_ref',jl.member_ref,'currency',pair.currency,'amount',pair.transfer_price))
 FROM ledger_line ll JOIN journal_line jl ON jl.tenant_id=ll.tenant_id AND jl.entity_id=ll.entity_id AND jl.journal_line_id=ll.journal_line_id WHERE ll.tenant_id=p_tenant AND ll.entity_id=pair.target_entity_id AND ll.journal_entry_id=pair.target_journal_entry_id AND ll.posting_batch_id=(target_result->>'posting_batch_id')::uuid AND ll.account_code=pair.target_due_to_account_code AND ll.credit_amount=pair.transfer_price AND ll.debit_amount=0 AND jl.dimensions->>'counterparty_entity_id'=pair.source_entity_id::text;
 IF (SELECT count(*) FROM unit_transfer_ic_open_item i WHERE i.tenant_id=p_tenant AND i.unit_transfer_pair_id=p_pair AND i.status='OPEN')<>2 THEN RAISE EXCEPTION 'Unit Transfer paired Post did not produce exact reciprocal IC open items' USING ERRCODE='23514';END IF;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'UNIT',pair.unit_control_id,'TRANSFERRED');$replacement$);
 IF patched=fn THEN RAISE EXCEPTION 'Unable to extend Unit Transfer Post with IC open items' USING ERRCODE='55000';END IF;BEGIN EXECUTE patched||';'; EXCEPTION WHEN syntax_error THEN RAISE EXCEPTION 'Unit Transfer migration post extension definition is invalid' USING ERRCODE='42601'; END;
END;
$unit_transfer_post_patch$;
REVOKE ALL ON FUNCTION refs_post_unit_transfer_pair_370(uuid,uuid,uuid,bigint,bigint,bigint,text,text) FROM PUBLIC,refs_app;

CREATE FUNCTION refs_unit_transfer_reversal_target_cost_snapshot(p_tenant uuid,p_pair unit_transfer_pair,p_property text,p_date date) RETURNS jsonb
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT refs_unit_transfer_cost_snapshot(p_tenant,p_pair.target_entity_id,p_date,p_property,p_pair.unit_ref,p_pair.currency,ARRAY[p_pair.target_inventory_account_code],NULL)
$$;

CREATE FUNCTION refs_unit_transfer_reversal_source_net(p_tenant uuid,p_pair unit_transfer_pair,p_property text,p_date date) RETURNS numeric
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT coalesce(sum(l.debit_amount-l.credit_amount),0)::numeric(20,4)
 FROM ledger_line l JOIN journal_entry j ON j.tenant_id=l.tenant_id AND j.entity_id=l.entity_id AND j.journal_entry_id=l.journal_entry_id AND j.status='POSTED'
 WHERE l.tenant_id=p_tenant AND l.entity_id=p_pair.source_entity_id AND l.currency=p_pair.currency AND l.account_code=ANY(p_pair.source_carrying_account_codes)
  AND l.dimensions->>'property_ref'=p_property AND l.dimensions->>'unit_ref'=p_pair.unit_ref AND j.journal_date<=p_date
$$;

CREATE FUNCTION refs_unit_transfer_ic_has_later_activity(p_tenant uuid,p_source unit_transfer_ic_open_item,p_target unit_transfer_ic_open_item) RETURNS boolean
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT EXISTS(
  SELECT 1 FROM (VALUES(p_source.entity_id,p_source.currency,p_source.account_code,p_source.counterparty_entity_id,p_source.counterparty_member_ref,p_source.ledger_line_id),(p_target.entity_id,p_target.currency,p_target.account_code,p_target.counterparty_entity_id,p_target.counterparty_member_ref,p_target.ledger_line_id)) scope(entity_id,currency,account_code,counterparty_entity_id,counterparty_member_ref,original_ledger_line_id)
  JOIN ledger_line original_line ON original_line.tenant_id=p_tenant AND original_line.entity_id=scope.entity_id AND original_line.ledger_line_id=scope.original_ledger_line_id
  JOIN ledger_line later ON later.tenant_id=p_tenant AND later.entity_id=scope.entity_id AND later.currency=scope.currency AND later.account_code=scope.account_code AND later.ledger_line_id<>scope.original_ledger_line_id AND later.posted_at>original_line.posted_at
  JOIN journal_entry later_journal ON later_journal.tenant_id=later.tenant_id AND later_journal.entity_id=later.entity_id AND later_journal.journal_entry_id=later.journal_entry_id AND later_journal.status='POSTED'
  WHERE later.member_ref=scope.counterparty_member_ref OR later.dimensions->>'counterparty_entity_id'=scope.counterparty_entity_id::text
 )
$$;

CREATE FUNCTION refs_create_unit_transfer_reversal_pair_hash(p_tenant uuid,p_entity uuid,p_pair uuid,p_expected_pair_revision bigint,p_expected_source_revision bigint,p_expected_target_revision bigint,p_reversal_date date,p_source_journal_number text,p_target_journal_number text,p_reason text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_REVERSAL_CREATE_V1','tenant_id',p_tenant,'entity_id',p_entity,'unit_transfer_pair_id',p_pair,'expected_pair_revision',p_expected_pair_revision,'expected_source_revision',p_expected_source_revision,'expected_target_revision',p_expected_target_revision,'reversal_date',p_reversal_date,'source_journal_number',btrim(p_source_journal_number),'target_journal_number',btrim(p_target_journal_number),'reason',btrim(p_reason)))
$$;

CREATE FUNCTION refs_create_unit_transfer_reversal_pair(p_tenant uuid,p_entity uuid,p_pair uuid,p_expected_pair_revision bigint,p_expected_source_revision bigint,p_expected_target_revision bigint,p_reversal_date date,p_source_journal_number text,p_target_journal_number text,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();idem idempotency_receipt;original_pair unit_transfer_pair;unit_control unit_transfer_unit_control;source_original_journal journal_entry;target_original_journal journal_entry;
 source_periods uuid[];target_periods uuid[];source_period uuid;target_period uuid;reversal_id uuid:=gen_random_uuid();source_reversal_journal uuid:=gen_random_uuid();target_reversal_journal uuid:=gen_random_uuid();
 target_snapshot jsonb;target_ids uuid[];expected_target_ids uuid[];source_net numeric(20,4);source_ic unit_transfer_ic_open_item;target_ic unit_transfer_ic_open_item;
 source_attachment_hash text;target_attachment_hash text;source_journal_hash text;target_journal_hash text;evidence text;payload jsonb;
BEGIN
 IF actor IS NULL OR p_reversal_date IS NULL OR p_expected_pair_revision IS NULL OR p_expected_pair_revision<0 OR p_expected_source_revision IS NULL OR p_expected_source_revision<0 OR p_expected_target_revision IS NULL OR p_expected_target_revision<0 OR length(btrim(coalesce(p_source_journal_number,''))) NOT BETWEEN 1 AND 100 OR length(btrim(coalesce(p_target_journal_number,''))) NOT BETWEEN 1 AND 100 OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 2000 OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS NULL OR p_request_hash!~'^sha256:[0-9a-f]{64}$' OR p_request_hash IS DISTINCT FROM refs_create_unit_transfer_reversal_pair_hash(p_tenant,p_entity,p_pair,p_expected_pair_revision,p_expected_source_revision,p_expected_target_revision,p_reversal_date,p_source_journal_number,p_target_journal_number,p_reason) THEN RAISE EXCEPTION 'Invalid Unit Transfer reversal create command' USING ERRCODE='22023';END IF;
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'UNIT_TRANSFER_REVERSAL_CREATE:'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;
 SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='UNIT_TRANSFER_REVERSAL_CREATE:'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;
 IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Unit Transfer reversal create idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 SELECT * INTO original_pair FROM unit_transfer_pair WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair AND p_entity IN(source_entity_id,target_entity_id) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unit Transfer pair not found' USING ERRCODE='P0002';END IF;
 PERFORM refs_assert_scope(p_tenant,original_pair.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVERSE');PERFORM refs_assert_scope(p_tenant,original_pair.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVERSE');
 PERFORM refs_assert_scope(p_tenant,original_pair.source_entity_id,'GL.JE.REVERSE');PERFORM refs_assert_scope(p_tenant,original_pair.target_entity_id,'GL.JE.REVERSE');PERFORM refs_assert_scope(p_tenant,original_pair.source_entity_id,'GL.JE.CREATE');PERFORM refs_assert_scope(p_tenant,original_pair.target_entity_id,'GL.JE.CREATE');
 IF actor=original_pair.created_by THEN RAISE EXCEPTION 'Unit Transfer reversal creator SoD violation' USING ERRCODE='42501';END IF;
 IF original_pair.status<>'POSTED_PAIR' OR original_pair.revision<>p_expected_pair_revision THEN RAISE EXCEPTION 'Original Unit Transfer is not Posted at the expected revision' USING ERRCODE='40001';END IF;
 IF p_reversal_date<original_pair.transfer_date THEN RAISE EXCEPTION 'Unit Transfer reversal date cannot precede the original transfer' USING ERRCODE='22023';END IF;
 SELECT * INTO unit_control FROM unit_transfer_unit_control WHERE tenant_id=p_tenant AND unit_control_id=original_pair.unit_control_id FOR UPDATE;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||unit_control.property_ref||':'||unit_control.unit_ref,0));
 IF unit_control.version<>original_pair.expected_unit_version+1 OR unit_control.last_transfer_pair_id IS DISTINCT FROM original_pair.unit_transfer_pair_id OR unit_control.current_owner_entity_id<>original_pair.target_entity_id OR unit_control.current_asset_account_codes<>ARRAY[original_pair.target_inventory_account_code] OR unit_control.lifecycle_stage<>original_pair.target_lifecycle_stage THEN RAISE EXCEPTION 'Only the latest ownership event can be reversed' USING ERRCODE='40001';END IF;
 IF EXISTS(SELECT 1 FROM unit_transfer_pair later WHERE later.tenant_id=p_tenant AND later.unit_control_id=original_pair.unit_control_id AND later.unit_transfer_pair_id<>p_pair AND later.status<>'CANCELLED_PAIR' AND later.created_at>original_pair.created_at) THEN RAISE EXCEPTION 'Only the latest ownership event can be reversed' USING ERRCODE='40001';END IF;
 SELECT * INTO source_original_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=original_pair.source_entity_id AND journal_entry_id=original_pair.source_journal_entry_id FOR UPDATE;
 SELECT * INTO target_original_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=original_pair.target_entity_id AND journal_entry_id=original_pair.target_journal_entry_id FOR UPDATE;
 IF source_original_journal.status<>'POSTED' OR target_original_journal.status<>'POSTED' OR source_original_journal.revision<>p_expected_source_revision OR target_original_journal.revision<>p_expected_target_revision THEN RAISE EXCEPTION 'Original Unit Transfer Journals changed' USING ERRCODE='40001';END IF;
 IF actor IN(source_original_journal.created_by,source_original_journal.reviewed_by,source_original_journal.approved_by,source_original_journal.posted_by,target_original_journal.created_by,target_original_journal.reviewed_by,target_original_journal.approved_by,target_original_journal.posted_by) THEN RAISE EXCEPTION 'Unit Transfer reversal creation SoD violation' USING ERRCODE='42501';END IF;
 SELECT array_agg(period_id ORDER BY period_id) INTO source_periods FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=original_pair.source_entity_id AND ledger_code='PRIMARY' AND status='OPEN' AND p_reversal_date BETWEEN starts_on AND ends_on;
 SELECT array_agg(period_id ORDER BY period_id) INTO target_periods FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=original_pair.target_entity_id AND ledger_code='PRIMARY' AND status='OPEN' AND p_reversal_date BETWEEN starts_on AND ends_on;
 IF cardinality(coalesce(source_periods,'{}'::uuid[]))<>1 OR cardinality(coalesce(target_periods,'{}'::uuid[]))<>1 THEN RAISE EXCEPTION 'Reversal date must resolve to one OPEN primary period in each company' USING ERRCODE='22023';END IF;source_period:=source_periods[1];target_period:=target_periods[1];
 target_snapshot:=refs_unit_transfer_reversal_target_cost_snapshot(p_tenant,original_pair,unit_control.property_ref,'9999-12-31'::date);target_ids:=ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(target_snapshot->'ledger_line_ids') value ORDER BY value::uuid);
 SELECT array_agg(l.ledger_line_id ORDER BY l.ledger_line_id) INTO expected_target_ids FROM ledger_line l WHERE l.tenant_id=p_tenant AND l.entity_id=original_pair.target_entity_id AND l.journal_entry_id=original_pair.target_journal_entry_id AND l.account_code=original_pair.target_inventory_account_code AND l.dimensions->>'property_ref'=unit_control.property_ref AND l.dimensions->>'unit_ref'=original_pair.unit_ref;
 IF target_snapshot IS NULL OR(target_snapshot->>'amount')::numeric<>original_pair.transfer_price OR target_ids IS DISTINCT FROM expected_target_ids THEN RAISE EXCEPTION 'Target Unit Transfer cost moved after Post' USING ERRCODE='55000';END IF;
 source_net:=refs_unit_transfer_reversal_source_net(p_tenant,original_pair,unit_control.property_ref,'9999-12-31'::date);IF source_net<>0 THEN RAISE EXCEPTION 'Source Unit Transfer cost is not zero after Post' USING ERRCODE='55000';END IF;
 SELECT * INTO source_ic FROM unit_transfer_ic_open_item WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair AND entity_id=original_pair.source_entity_id AND counterparty_entity_id=original_pair.target_entity_id AND direction='DUE_FROM' FOR UPDATE;
 SELECT * INTO target_ic FROM unit_transfer_ic_open_item WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair AND entity_id=original_pair.target_entity_id AND counterparty_entity_id=original_pair.source_entity_id AND direction='DUE_TO' FOR UPDATE;
 IF source_ic.unit_transfer_ic_open_item_id IS NULL OR target_ic.unit_transfer_ic_open_item_id IS NULL OR source_ic.status<>'OPEN' OR target_ic.status<>'OPEN' OR source_ic.currency<>original_pair.currency OR target_ic.currency<>original_pair.currency OR source_ic.original_amount<>original_pair.transfer_price OR target_ic.original_amount<>original_pair.transfer_price OR source_ic.remaining_amount<>original_pair.transfer_price OR target_ic.remaining_amount<>original_pair.transfer_price OR source_ic.journal_entry_id<>original_pair.source_journal_entry_id OR target_ic.journal_entry_id<>original_pair.target_journal_entry_id OR source_ic.account_code<>original_pair.source_due_from_account_code OR target_ic.account_code<>original_pair.target_due_to_account_code THEN RAISE EXCEPTION 'Authoritative unsettled Unit Transfer IC open items are unavailable' USING ERRCODE='0A000';END IF;
 IF refs_unit_transfer_ic_has_later_activity(p_tenant,source_ic,target_ic) THEN RAISE EXCEPTION 'Unit Transfer IC accounts have later Posted activity that may represent settlement' USING ERRCODE='55000';END IF;
 source_attachment_hash:=refs_unit_transfer_attachment_ids_snapshot(p_tenant,original_pair.source_entity_id,original_pair.attachment_ids);target_attachment_hash:=refs_unit_transfer_attachment_ids_snapshot(p_tenant,original_pair.target_entity_id,original_pair.target_attachment_ids);
 IF source_attachment_hash IS DISTINCT FROM original_pair.attachment_snapshot_hash OR target_attachment_hash IS DISTINCT FROM original_pair.target_attachment_snapshot_hash THEN RAISE EXCEPTION 'Unit Transfer reversal attachment evidence changed' USING ERRCODE='40001';END IF;
 INSERT INTO journal_entry(journal_entry_id,tenant_id,entity_id,period_id,journal_number,journal_type,status,journal_date,currency,description,created_by,reversal_of_id) VALUES
  (source_reversal_journal,p_tenant,original_pair.source_entity_id,source_period,btrim(p_source_journal_number),'REVERSAL','DRAFT',p_reversal_date,original_pair.currency,btrim(p_reason),actor,NULL),
  (target_reversal_journal,p_tenant,original_pair.target_entity_id,target_period,btrim(p_target_journal_number),'REVERSAL','DRAFT',p_reversal_date,original_pair.currency,btrim(p_reason),actor,NULL);
 INSERT INTO journal_line(journal_line_id,tenant_id,entity_id,period_id,journal_entry_id,line_no,account_code,debit_amount,credit_amount,member_ref,description,dimensions)
  SELECT gen_random_uuid(),p_tenant,original_pair.source_entity_id,source_period,source_reversal_journal,original_line.line_no,original_line.account_code,original_line.credit_amount,original_line.debit_amount,original_line.member_ref,original_line.description,original_line.dimensions FROM journal_line original_line WHERE original_line.tenant_id=p_tenant AND original_line.entity_id=original_pair.source_entity_id AND original_line.journal_entry_id=original_pair.source_journal_entry_id ORDER BY original_line.line_no;
 INSERT INTO journal_line(journal_line_id,tenant_id,entity_id,period_id,journal_entry_id,line_no,account_code,debit_amount,credit_amount,member_ref,description,dimensions)
  SELECT gen_random_uuid(),p_tenant,original_pair.target_entity_id,target_period,target_reversal_journal,original_line.line_no,original_line.account_code,original_line.credit_amount,original_line.debit_amount,original_line.member_ref,original_line.description,original_line.dimensions FROM journal_line original_line WHERE original_line.tenant_id=p_tenant AND original_line.entity_id=original_pair.target_entity_id AND original_line.journal_entry_id=original_pair.target_journal_entry_id ORDER BY original_line.line_no;
 INSERT INTO source_link(tenant_id,entity_id,link_type,journal_entry_id,attachment_id,created_by) SELECT p_tenant,original_pair.source_entity_id,'JE_ATTACHMENT',source_reversal_journal,value,actor FROM unnest(original_pair.attachment_ids) value;
 INSERT INTO source_link(tenant_id,entity_id,link_type,journal_entry_id,attachment_id,created_by) SELECT p_tenant,original_pair.target_entity_id,'JE_ATTACHMENT',target_reversal_journal,value,actor FROM unnest(original_pair.target_attachment_ids) value;
 source_journal_hash:=refs_unit_transfer_journal_snapshot(p_tenant,original_pair.source_entity_id,source_reversal_journal);target_journal_hash:=refs_unit_transfer_journal_snapshot(p_tenant,original_pair.target_entity_id,target_reversal_journal);
 evidence:=refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_REVERSAL_EVIDENCE_V1','unit_transfer_reversal_pair_id',reversal_id,'original_unit_transfer_pair_id',p_pair,'unit_control_id',unit_control.unit_control_id,'expected_unit_version',unit_control.version,'expected_prior_reversal_id',unit_control.last_transfer_reversal_id,'expected_original_pair_revision',original_pair.revision,'source_original_journal_entry_id',original_pair.source_journal_entry_id,'source_original_revision',source_original_journal.revision,'target_original_journal_entry_id',original_pair.target_journal_entry_id,'target_original_revision',target_original_journal.revision,'source_reversal_journal_entry_id',source_reversal_journal,'target_reversal_journal_entry_id',target_reversal_journal,'target_cost_ledger_line_ids',to_jsonb(target_ids),'target_cost_basis_hash',target_snapshot->>'basis_hash','source_ic_open_item_id',source_ic.unit_transfer_ic_open_item_id,'source_ic_version',source_ic.version,'target_ic_open_item_id',target_ic.unit_transfer_ic_open_item_id,'target_ic_version',target_ic.version,'reason',btrim(p_reason)));
 INSERT INTO unit_transfer_reversal_pair(unit_transfer_reversal_pair_id,tenant_id,original_unit_transfer_pair_id,unit_control_id,source_entity_id,target_entity_id,source_period_id,target_period_id,reversal_date,currency,source_original_journal_entry_id,target_original_journal_entry_id,source_reversal_journal_entry_id,target_reversal_journal_entry_id,source_ic_open_item_id,target_ic_open_item_id,expected_source_ic_version,expected_target_ic_version,expected_unit_version,expected_prior_reversal_id,expected_original_pair_revision,expected_source_original_revision,expected_target_original_revision,target_cost_ledger_line_ids,target_cost_basis_hash,source_reversal_journal_snapshot_hash,target_reversal_journal_snapshot_hash,source_attachment_snapshot_hash,target_attachment_snapshot_hash,reason,evidence_hash,created_by)
 VALUES(reversal_id,p_tenant,p_pair,unit_control.unit_control_id,original_pair.source_entity_id,original_pair.target_entity_id,source_period,target_period,p_reversal_date,original_pair.currency,original_pair.source_journal_entry_id,original_pair.target_journal_entry_id,source_reversal_journal,target_reversal_journal,source_ic.unit_transfer_ic_open_item_id,target_ic.unit_transfer_ic_open_item_id,source_ic.version,target_ic.version,unit_control.version,unit_control.last_transfer_reversal_id,original_pair.revision,source_original_journal.revision,target_original_journal.revision,target_ids,target_snapshot->>'basis_hash',source_journal_hash,target_journal_hash,source_attachment_hash,target_attachment_hash,btrim(p_reason),evidence,actor);
 payload:=jsonb_build_object('schema_version','UNIT_TRANSFER_REVERSAL_DRAFT_PAIR_V1','unit_transfer_reversal_pair_id',reversal_id,'original_unit_transfer_pair_id',p_pair,'source_entity_id',original_pair.source_entity_id,'target_entity_id',original_pair.target_entity_id,'source_period_id',source_period,'target_period_id',target_period,'reversal_date',p_reversal_date,'source_reversal_journal_entry_id',source_reversal_journal,'target_reversal_journal_entry_id',target_reversal_journal,'status','DRAFT_PAIR','revision',0,'evidence_hash',evidence,'idempotent',false);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,original_pair.source_entity_id,'UNIT_TRANSFER_REVERSAL_DRAFT_CREATED','UNIT_TRANSFER_REVERSAL_PAIR',reversal_id,'CREATE',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.REVERSE',p_idempotency_key,p_idempotency_key,p_idempotency_key,evidence,btrim(p_reason),payload),(p_tenant,original_pair.target_entity_id,'UNIT_TRANSFER_REVERSAL_DRAFT_CREATED','UNIT_TRANSFER_REVERSAL_PAIR',reversal_id,'CREATE',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.REVERSE',p_idempotency_key,p_idempotency_key,p_idempotency_key,evidence,btrim(p_reason),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,original_pair.source_entity_id,'UNIT_TRANSFER_REVERSAL_PAIR',reversal_id,'UNIT_TRANSFER_REVERSAL_DRAFT_CREATED',payload,refs_jsonb_hash(payload)),(p_tenant,original_pair.target_entity_id,'UNIT_TRANSFER_REVERSAL_PAIR',reversal_id,'UNIT_TRANSFER_REVERSAL_DRAFT_CREATED',payload,refs_jsonb_hash(payload));
 UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=201,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;
END;$$;

-- Preserve the exact 370 trigger functions so down can restore them without
-- embedding a stale copy of an applied migration.
DO $unit_transfer_journal_guard_patch$
DECLARE fn text; patched text;
BEGIN
 fn:=pg_get_functiondef('refs_guard_unit_transfer_journal_transition()'::regprocedure);
 patched:=replace(fn,'public.refs_guard_unit_transfer_journal_transition()','public.refs_guard_unit_transfer_journal_transition_370()');
 IF patched=fn THEN RAISE EXCEPTION 'Unable to retain 370 Unit Transfer Journal guard' USING ERRCODE='55000'; END IF;
 EXECUTE patched||';';
 patched:=replace(fn,'DECLARE pair unit_transfer_pair;gate integer;','DECLARE pair unit_transfer_pair;reversal_pair unit_transfer_reversal_pair;gate integer;');
 patched:=replace(patched,$needle$ SELECT * INTO pair FROM unit_transfer_pair WHERE tenant_id=NEW.tenant_id$needle$,$replacement$ SELECT * INTO reversal_pair FROM unit_transfer_reversal_pair r WHERE r.tenant_id=NEW.tenant_id AND(r.source_entity_id=NEW.entity_id AND r.source_reversal_journal_entry_id=NEW.journal_entry_id OR r.target_entity_id=NEW.entity_id AND r.target_reversal_journal_entry_id=NEW.journal_entry_id) FOR UPDATE;
 IF FOUND THEN
  IF NEW.reversal_of_id IS DISTINCT FROM OLD.reversal_of_id THEN
   DELETE FROM unit_transfer_internal_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=NEW.tenant_id AND unit_transfer_pair_id=reversal_pair.unit_transfer_reversal_pair_id AND resource_kind='HEADER' AND resource_id=NEW.journal_entry_id AND operation='BIND_REVERSAL' RETURNING 1 INTO gate;
   IF gate IS NULL OR OLD.reversal_of_id IS NOT NULL OR NEW.reversal_of_id IS DISTINCT FROM CASE WHEN NEW.journal_entry_id=reversal_pair.source_reversal_journal_entry_id THEN reversal_pair.source_original_journal_entry_id ELSE reversal_pair.target_original_journal_entry_id END OR NEW.status IS DISTINCT FROM OLD.status OR (NEW.journal_entry_id,NEW.tenant_id,NEW.entity_id,NEW.period_id,NEW.journal_number,NEW.journal_type,NEW.journal_date,NEW.currency,NEW.description,NEW.created_by,NEW.reviewed_by,NEW.approved_by,NEW.posted_by,NEW.posted_at,NEW.revision,NEW.reclass_of_id,NEW.created_at) IS DISTINCT FROM (OLD.journal_entry_id,OLD.tenant_id,OLD.entity_id,OLD.period_id,OLD.journal_number,OLD.journal_type,OLD.journal_date,OLD.currency,OLD.description,OLD.created_by,OLD.reviewed_by,OLD.approved_by,OLD.posted_by,OLD.posted_at,OLD.revision,OLD.reclass_of_id,OLD.created_at) THEN RAISE EXCEPTION 'Unit Transfer reversal header binding is unauthorized' USING ERRCODE='55000';END IF;
  ELSE
   IF NEW.status IS NOT DISTINCT FROM OLD.status OR (NEW.journal_entry_id,NEW.tenant_id,NEW.entity_id,NEW.period_id,NEW.journal_number,NEW.journal_type,NEW.journal_date,NEW.currency,NEW.description,NEW.created_by,NEW.reversal_of_id,NEW.reclass_of_id,NEW.created_at) IS DISTINCT FROM (OLD.journal_entry_id,OLD.tenant_id,OLD.entity_id,OLD.period_id,OLD.journal_number,OLD.journal_type,OLD.journal_date,OLD.currency,OLD.description,OLD.created_by,OLD.reversal_of_id,OLD.reclass_of_id,OLD.created_at) THEN RAISE EXCEPTION 'Unit Transfer reversal Journal headers are retained evidence' USING ERRCODE='55000';END IF;
   DELETE FROM unit_transfer_internal_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=NEW.tenant_id AND unit_transfer_pair_id=reversal_pair.unit_transfer_reversal_pair_id AND resource_kind='JOURNAL' AND resource_id=NEW.journal_entry_id AND operation=NEW.status RETURNING 1 INTO gate;
   IF gate IS NULL THEN RAISE EXCEPTION 'Unit Transfer reversal Journals must transition as one authorized pair' USING ERRCODE='0A000';END IF;
   IF reversal_pair.source_reversal_journal_snapshot_hash<>refs_unit_transfer_journal_snapshot(reversal_pair.tenant_id,reversal_pair.source_entity_id,reversal_pair.source_reversal_journal_entry_id) OR reversal_pair.target_reversal_journal_snapshot_hash<>refs_unit_transfer_journal_snapshot(reversal_pair.tenant_id,reversal_pair.target_entity_id,reversal_pair.target_reversal_journal_entry_id) THEN RAISE EXCEPTION 'Unit Transfer reversal financial lines changed' USING ERRCODE='23514';END IF;
  END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO pair FROM unit_transfer_pair WHERE tenant_id=NEW.tenant_id$replacement$);
 IF patched=fn OR patched NOT LIKE '%unit_transfer_reversal_pair%' THEN RAISE EXCEPTION 'Unable to extend Unit Transfer Journal guard' USING ERRCODE='55000'; END IF;
 EXECUTE patched||';';
END;
$unit_transfer_journal_guard_patch$;
REVOKE ALL ON FUNCTION refs_guard_unit_transfer_journal_transition_370() FROM PUBLIC,refs_app;

CREATE FUNCTION refs_guard_unit_transfer_reversal_line() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE t uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.tenant_id ELSE NEW.tenant_id END;e uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.entity_id ELSE NEW.entity_id END;j uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.journal_entry_id ELSE NEW.journal_entry_id END;
BEGIN IF EXISTS(SELECT 1 FROM unit_transfer_reversal_pair r WHERE r.tenant_id=t AND(r.source_entity_id=e AND r.source_reversal_journal_entry_id=j OR r.target_entity_id=e AND r.target_reversal_journal_entry_id=j)) THEN RAISE EXCEPTION 'Unit Transfer reversal Journal lines are retained evidence' USING ERRCODE='55000';END IF;RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END;$$;
CREATE TRIGGER unit_transfer_reversal_journal_line_guard BEFORE INSERT OR UPDATE OR DELETE ON journal_line FOR EACH ROW EXECUTE FUNCTION refs_guard_unit_transfer_reversal_line();

CREATE FUNCTION refs_guard_unit_transfer_reversal_source_link() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE t uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.tenant_id ELSE NEW.tenant_id END;e uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.entity_id ELSE NEW.entity_id END;j uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.journal_entry_id ELSE NEW.journal_entry_id END;r unit_transfer_reversal_pair;
BEGIN SELECT * INTO r FROM unit_transfer_reversal_pair x WHERE x.tenant_id=t AND(x.source_entity_id=e AND x.source_reversal_journal_entry_id=j OR x.target_entity_id=e AND x.target_reversal_journal_entry_id=j);
 IF FOUND AND NOT(TG_OP='INSERT' AND NEW.link_type='JE_LINE_TO_LEDGER' AND EXISTS(SELECT 1 FROM unit_transfer_internal_gate g WHERE g.backend_pid=pg_backend_pid() AND g.transaction_id=txid_current() AND g.tenant_id=t AND g.unit_transfer_pair_id=r.unit_transfer_reversal_pair_id AND g.resource_kind='JOURNAL' AND g.resource_id=j AND g.operation='POSTED')) THEN RAISE EXCEPTION 'Unit Transfer reversal Journal lineage is retained evidence' USING ERRCODE='55000';END IF;RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END;$$;
CREATE TRIGGER unit_transfer_reversal_source_link_guard BEFORE INSERT OR UPDATE OR DELETE ON source_link FOR EACH ROW EXECUTE FUNCTION refs_guard_unit_transfer_reversal_source_link();

CREATE FUNCTION refs_protect_unit_transfer_reversal_pair() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE gate integer;
BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Unit Transfer reversal evidence is immutable' USING ERRCODE='55000';END IF;
 DELETE FROM unit_transfer_internal_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=NEW.tenant_id AND unit_transfer_pair_id=NEW.unit_transfer_reversal_pair_id AND resource_kind='PAIR' AND resource_id=NEW.unit_transfer_reversal_pair_id AND operation=NEW.status RETURNING 1 INTO gate;
 IF gate IS NULL OR NEW.revision<>OLD.revision+1 OR (to_jsonb(NEW)-ARRAY['status','revision','completed_at','cancelled_by','cancelled_at','cancel_reason']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','completed_at','cancelled_by','cancelled_at','cancel_reason']) THEN RAISE EXCEPTION 'Unit Transfer reversal evidence is immutable' USING ERRCODE='55000';END IF;
 IF NOT(OLD.status='DRAFT_PAIR' AND NEW.status IN('PENDING_REVIEW_PAIR','CANCELLED_PAIR') OR OLD.status='PENDING_REVIEW_PAIR' AND NEW.status IN('PENDING_APPROVAL_PAIR','DRAFT_PAIR') OR OLD.status='PENDING_APPROVAL_PAIR' AND NEW.status IN('APPROVED_PAIR','DRAFT_PAIR') OR OLD.status='APPROVED_PAIR' AND NEW.status='POSTED_PAIR') THEN RAISE EXCEPTION 'Unit Transfer reversal lifecycle transition is invalid' USING ERRCODE='55000';END IF;
 RETURN NEW;END;$$;
CREATE TRIGGER unit_transfer_reversal_pair_protect BEFORE UPDATE OR DELETE ON unit_transfer_reversal_pair FOR EACH ROW EXECUTE FUNCTION refs_protect_unit_transfer_reversal_pair();

DO $unit_transfer_unit_protect_patch$DECLARE fn text;BEGIN fn:=pg_get_functiondef('refs_protect_unit_transfer_unit()'::regprocedure);BEGIN EXECUTE replace(fn,'public.refs_protect_unit_transfer_unit()','public.refs_protect_unit_transfer_unit_370()')||';'; EXCEPTION WHEN syntax_error THEN RAISE EXCEPTION 'Unit Transfer migration unit protection backup definition is invalid' USING ERRCODE='42601'; END;END;
$unit_transfer_unit_protect_patch$;
REVOKE ALL ON FUNCTION refs_protect_unit_transfer_unit_370() FROM PUBLIC,refs_app;
CREATE OR REPLACE FUNCTION refs_protect_unit_transfer_unit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE gate integer;op_name text:=CASE WHEN NEW.last_transfer_reversal_id IS DISTINCT FROM OLD.last_transfer_reversal_id THEN 'REVERSED' WHEN NEW.last_transfer_pair_id IS DISTINCT FROM OLD.last_transfer_pair_id THEN 'TRANSFERRED' ELSE 'REBASELINED' END;
BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Unit ownership evidence is immutable outside controlled Unit Transfer commands' USING ERRCODE='55000';END IF;
 DELETE FROM unit_transfer_internal_gate g WHERE g.backend_pid=pg_backend_pid() AND g.transaction_id=txid_current() AND g.tenant_id=NEW.tenant_id AND g.resource_kind='UNIT' AND g.resource_id=NEW.unit_control_id AND g.operation=op_name AND(op_name='REBASELINED' OR op_name='REVERSED' AND g.unit_transfer_pair_id=NEW.last_transfer_reversal_id OR op_name='TRANSFERRED' AND g.unit_transfer_pair_id=NEW.last_transfer_pair_id) RETURNING 1 INTO gate;
 IF gate IS NULL OR (NEW.tenant_id,NEW.property_ref,NEW.unit_ref,NEW.currency,NEW.initial_owner_entity_id,NEW.initial_source_document_id,NEW.initial_source_document_line_id,NEW.initial_source_payload_hash,NEW.created_by,NEW.created_at) IS DISTINCT FROM(OLD.tenant_id,OLD.property_ref,OLD.unit_ref,OLD.currency,OLD.initial_owner_entity_id,OLD.initial_source_document_id,OLD.initial_source_document_line_id,OLD.initial_source_payload_hash,OLD.created_by,OLD.created_at) OR NEW.version<>OLD.version+1 OR op_name='REBASELINED' AND(NEW.current_owner_entity_id<>OLD.current_owner_entity_id OR NEW.last_transfer_pair_id IS DISTINCT FROM OLD.last_transfer_pair_id OR NEW.last_transfer_reversal_id IS DISTINCT FROM OLD.last_transfer_reversal_id) OR op_name='TRANSFERRED' AND NEW.last_transfer_reversal_id IS DISTINCT FROM OLD.last_transfer_reversal_id OR op_name='REVERSED' AND NEW.last_transfer_pair_id IS DISTINCT FROM OLD.last_transfer_pair_id THEN RAISE EXCEPTION 'Unit ownership evidence is immutable outside controlled Unit Transfer commands' USING ERRCODE='55000';END IF;RETURN NEW;END;$$;

CREATE FUNCTION refs_unit_transfer_reversal_transition_hash(p_tenant uuid,p_entity uuid,p_original_pair uuid,p_reversal_pair uuid,p_action text,p_expected_pair_revision bigint,p_expected_source_reversal_revision bigint,p_expected_target_reversal_revision bigint,p_reason text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$SELECT refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_REVERSAL_TRANSITION_V1','tenant_id',p_tenant,'entity_id',p_entity,'original_unit_transfer_pair_id',p_original_pair,'unit_transfer_reversal_pair_id',p_reversal_pair,'action',upper(p_action),'expected_pair_revision',p_expected_pair_revision,'expected_source_reversal_revision',p_expected_source_reversal_revision,'expected_target_reversal_revision',p_expected_target_reversal_revision,'reason',NULLIF(btrim(p_reason),'')))$$;
CREATE FUNCTION refs_transition_unit_transfer_reversal_pair(p_tenant uuid,p_entity uuid,p_original_pair uuid,p_reversal_pair uuid,p_action text,p_expected_pair_revision bigint,p_expected_source_reversal_revision bigint,p_expected_target_reversal_revision bigint,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();r unit_transfer_reversal_pair;idem idempotency_receipt;action text:=upper(p_action);target_pair_status text;target_journal_status text;source_result jsonb;target_result jsonb;h text;payload jsonb;
BEGIN IF action NOT IN('SUBMIT','REVIEW','APPROVE','REJECT') OR p_request_hash IS DISTINCT FROM refs_unit_transfer_reversal_transition_hash(p_tenant,p_entity,p_original_pair,p_reversal_pair,p_action,p_expected_pair_revision,p_expected_source_reversal_revision,p_expected_target_reversal_revision,p_reason) OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 THEN RAISE EXCEPTION 'Invalid Unit Transfer reversal transition command' USING ERRCODE='22023';END IF;
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'UNIT_TRANSFER_REVERSAL_TRANSITION:'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='UNIT_TRANSFER_REVERSAL_TRANSITION:'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Unit Transfer reversal transition idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 SELECT * INTO r FROM unit_transfer_reversal_pair WHERE tenant_id=p_tenant AND original_unit_transfer_pair_id=p_original_pair AND unit_transfer_reversal_pair_id=p_reversal_pair AND p_entity IN(source_entity_id,target_entity_id) FOR UPDATE;IF NOT FOUND OR r.revision<>p_expected_pair_revision THEN RAISE EXCEPTION 'Unit Transfer reversal pair revision conflict' USING ERRCODE='40001';END IF;
 PERFORM refs_assert_scope(p_tenant,r.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.'||action);PERFORM refs_assert_scope(p_tenant,r.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.'||action);PERFORM refs_assert_scope(p_tenant,r.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVERSE');PERFORM refs_assert_scope(p_tenant,r.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVERSE');
 IF action='SUBMIT' AND r.status='DRAFT_PAIR' THEN target_pair_status:='PENDING_REVIEW_PAIR';target_journal_status:='PENDING_REVIEW';ELSIF action='REVIEW' AND r.status='PENDING_REVIEW_PAIR' THEN target_pair_status:='PENDING_APPROVAL_PAIR';target_journal_status:='PENDING_APPROVAL';ELSIF action='APPROVE' AND r.status='PENDING_APPROVAL_PAIR' THEN target_pair_status:='APPROVED_PAIR';target_journal_status:='APPROVED';ELSIF action='REJECT' AND r.status IN('PENDING_REVIEW_PAIR','PENDING_APPROVAL_PAIR') THEN target_pair_status:='DRAFT_PAIR';target_journal_status:='DRAFT';ELSE RAISE EXCEPTION 'Invalid Unit Transfer reversal lifecycle transition' USING ERRCODE='55000';END IF;
 IF actor=r.created_by OR action='APPROVE' AND EXISTS(SELECT 1 FROM journal_entry j WHERE j.tenant_id=p_tenant AND j.journal_entry_id IN(r.source_reversal_journal_entry_id,r.target_reversal_journal_entry_id) AND actor IN(j.created_by,j.reviewed_by)) THEN RAISE EXCEPTION 'Unit Transfer reversal SoD violation' USING ERRCODE='42501';END IF;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_reversal_pair,'JOURNAL',r.source_reversal_journal_entry_id,target_journal_status);h:=refs_journal_transition_hash(p_tenant,r.source_entity_id,r.source_reversal_journal_entry_id,action,p_expected_source_reversal_revision,NULLIF(btrim(p_reason),''));source_result:=refs_transition_journal(p_tenant,r.source_entity_id,r.source_reversal_journal_entry_id,action,p_expected_source_reversal_revision,NULLIF(btrim(p_reason),''),'unit-transfer-reversal:'||p_reversal_pair||':source:'||p_idempotency_key,h);
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_reversal_pair,'JOURNAL',r.target_reversal_journal_entry_id,target_journal_status);h:=refs_journal_transition_hash(p_tenant,r.target_entity_id,r.target_reversal_journal_entry_id,action,p_expected_target_reversal_revision,NULLIF(btrim(p_reason),''));target_result:=refs_transition_journal(p_tenant,r.target_entity_id,r.target_reversal_journal_entry_id,action,p_expected_target_reversal_revision,NULLIF(btrim(p_reason),''),'unit-transfer-reversal:'||p_reversal_pair||':target:'||p_idempotency_key,h);
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_reversal_pair,'PAIR',p_reversal_pair,target_pair_status);UPDATE unit_transfer_reversal_pair SET status=target_pair_status,revision=revision+1 WHERE tenant_id=p_tenant AND unit_transfer_reversal_pair_id=p_reversal_pair;
 payload:=jsonb_build_object('schema_version','UNIT_TRANSFER_REVERSAL_TRANSITION_RECEIPT_V1','unit_transfer_reversal_pair_id',p_reversal_pair,'original_unit_transfer_pair_id',p_original_pair,'status',target_pair_status,'revision',r.revision+1,'source_journal',source_result,'target_journal',target_result,'idempotent',false);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,r.source_entity_id,'UNIT_TRANSFER_REVERSAL_'||action,'UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair,action,actor,'USER','REAL_ESTATE.UNIT_TRANSFER.'||action,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),NULLIF(btrim(p_reason),''),payload),(p_tenant,r.target_entity_id,'UNIT_TRANSFER_REVERSAL_'||action,'UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair,action,actor,'USER','REAL_ESTATE.UNIT_TRANSFER.'||action,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),NULLIF(btrim(p_reason),''),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,r.source_entity_id,'UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair,'UNIT_TRANSFER_REVERSAL_'||action,payload,refs_jsonb_hash(payload)),(p_tenant,r.target_entity_id,'UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair,'UNIT_TRANSFER_REVERSAL_'||action,payload,refs_jsonb_hash(payload));UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;
END;$$;

CREATE FUNCTION refs_unit_transfer_reversal_cancel_hash(p_tenant uuid,p_entity uuid,p_original_pair uuid,p_reversal_pair uuid,p_expected_pair_revision bigint,p_expected_source_reversal_revision bigint,p_expected_target_reversal_revision bigint,p_reason text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$SELECT refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_REVERSAL_CANCEL_V1','tenant_id',p_tenant,'entity_id',p_entity,'original_unit_transfer_pair_id',p_original_pair,'unit_transfer_reversal_pair_id',p_reversal_pair,'expected_pair_revision',p_expected_pair_revision,'expected_source_reversal_revision',p_expected_source_reversal_revision,'expected_target_reversal_revision',p_expected_target_reversal_revision,'reason',btrim(p_reason)))$$;
CREATE FUNCTION refs_cancel_unit_transfer_reversal_pair(p_tenant uuid,p_entity uuid,p_original_pair uuid,p_reversal_pair uuid,p_expected_pair_revision bigint,p_expected_source_reversal_revision bigint,p_expected_target_reversal_revision bigint,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();r unit_transfer_reversal_pair;source_journal journal_entry;target_journal journal_entry;idem idempotency_receipt;payload jsonb;
BEGIN IF length(btrim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 2000 OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS DISTINCT FROM refs_unit_transfer_reversal_cancel_hash(p_tenant,p_entity,p_original_pair,p_reversal_pair,p_expected_pair_revision,p_expected_source_reversal_revision,p_expected_target_reversal_revision,p_reason) THEN RAISE EXCEPTION 'Invalid Unit Transfer reversal cancel command' USING ERRCODE='22023';END IF;
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'UNIT_TRANSFER_REVERSAL_CANCEL:'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='UNIT_TRANSFER_REVERSAL_CANCEL:'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Unit Transfer reversal cancel idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 SELECT * INTO r FROM unit_transfer_reversal_pair WHERE tenant_id=p_tenant AND original_unit_transfer_pair_id=p_original_pair AND unit_transfer_reversal_pair_id=p_reversal_pair AND p_entity IN(source_entity_id,target_entity_id) FOR UPDATE;SELECT * INTO source_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=r.source_entity_id AND journal_entry_id=r.source_reversal_journal_entry_id FOR UPDATE;SELECT * INTO target_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=r.target_entity_id AND journal_entry_id=r.target_reversal_journal_entry_id FOR UPDATE;
 IF r.status<>'DRAFT_PAIR' OR r.revision<>p_expected_pair_revision OR source_journal.status<>'DRAFT' OR target_journal.status<>'DRAFT' OR source_journal.revision<>p_expected_source_reversal_revision OR target_journal.revision<>p_expected_target_reversal_revision THEN RAISE EXCEPTION 'Only the expected reversal Draft pair can be cancelled' USING ERRCODE='40001';END IF;
 PERFORM refs_assert_scope(p_tenant,r.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.CANCEL');PERFORM refs_assert_scope(p_tenant,r.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.CANCEL');PERFORM refs_assert_scope(p_tenant,r.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVERSE');PERFORM refs_assert_scope(p_tenant,r.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVERSE');IF actor=r.created_by THEN RAISE EXCEPTION 'Unit Transfer reversal cancellation SoD violation' USING ERRCODE='42501';END IF;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_reversal_pair,'PAIR',p_reversal_pair,'CANCELLED_PAIR');UPDATE unit_transfer_reversal_pair SET status='CANCELLED_PAIR',revision=revision+1,cancelled_by=actor,cancelled_at=clock_timestamp(),cancel_reason=btrim(p_reason) WHERE tenant_id=p_tenant AND unit_transfer_reversal_pair_id=p_reversal_pair;
 payload:=jsonb_build_object('schema_version','UNIT_TRANSFER_REVERSAL_CANCEL_RECEIPT_V1','unit_transfer_reversal_pair_id',p_reversal_pair,'original_unit_transfer_pair_id',p_original_pair,'status','CANCELLED_PAIR','revision',r.revision+1,'source_reversal_journal_entry_id',r.source_reversal_journal_entry_id,'source_reversal_journal_revision',source_journal.revision,'target_reversal_journal_entry_id',r.target_reversal_journal_entry_id,'target_reversal_journal_revision',target_journal.revision,'cancelled_by',actor,'cancelled_at',clock_timestamp(),'cancel_reason',btrim(p_reason),'evidence_hash',r.evidence_hash,'idempotent',false);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,r.source_entity_id,'UNIT_TRANSFER_REVERSAL_CANCELLED','UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair,'CANCEL',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.CANCEL',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload),(p_tenant,r.target_entity_id,'UNIT_TRANSFER_REVERSAL_CANCELLED','UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair,'CANCEL',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.CANCEL',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,r.source_entity_id,'UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair,'UNIT_TRANSFER_REVERSAL_CANCELLED',payload,refs_jsonb_hash(payload)),(p_tenant,r.target_entity_id,'UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair,'UNIT_TRANSFER_REVERSAL_CANCELLED',payload,refs_jsonb_hash(payload));UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;END;$$;

CREATE FUNCTION refs_unit_transfer_reversal_post_hash(p_tenant uuid,p_entity uuid,p_original_pair uuid,p_reversal_pair uuid,p_expected_reversal_pair_revision bigint,p_expected_source_reversal_revision bigint,p_expected_target_reversal_revision bigint) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$SELECT refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_REVERSAL_POST_V1','tenant_id',p_tenant,'entity_id',p_entity,'original_unit_transfer_pair_id',p_original_pair,'unit_transfer_reversal_pair_id',p_reversal_pair,'expected_reversal_pair_revision',p_expected_reversal_pair_revision,'expected_source_reversal_revision',p_expected_source_reversal_revision,'expected_target_reversal_revision',p_expected_target_reversal_revision))$$;

CREATE FUNCTION refs_post_unit_transfer_reversal_journal(p_tenant uuid,p_entity uuid,p_period uuid,p_reversal_pair uuid,p_journal uuid,p_original uuid,p_expected_revision bigint,p_idempotency_key text,p_request_hash text,p_actor text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE je journal_entry;original journal_entry;batch_id uuid:=gen_random_uuid();balanced boolean;line_count bigint;payload jsonb;
BEGIN SELECT * INTO je FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period AND journal_entry_id=p_journal FOR UPDATE;SELECT * INTO original FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=p_entity AND journal_entry_id=p_original FOR UPDATE;
 IF je.status<>'APPROVED' OR je.revision<>p_expected_revision OR je.journal_type<>'REVERSAL' OR je.reversal_of_id IS DISTINCT FROM p_original OR original.status<>'POSTED' OR p_actor IN(je.created_by,je.reviewed_by,je.approved_by) THEN RAISE EXCEPTION 'Unit Transfer reversal Journal cannot Post' USING ERRCODE='55000';END IF;
 IF NOT EXISTS(SELECT 1 FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period AND ledger_code='PRIMARY' AND status='OPEN' FOR UPDATE) THEN RAISE EXCEPTION 'Unit Transfer reversal period is not OPEN' USING ERRCODE='55000';END IF;
 SELECT count(*),coalesce(sum(debit_amount),0)=coalesce(sum(credit_amount),0) AND coalesce(sum(debit_amount),0)>0 INTO line_count,balanced FROM journal_line WHERE tenant_id=p_tenant AND entity_id=p_entity AND journal_entry_id=p_journal;
 IF line_count<2 OR NOT balanced OR line_count<>(SELECT count(*) FROM journal_line WHERE tenant_id=p_tenant AND entity_id=p_entity AND journal_entry_id=p_original) OR EXISTS(SELECT 1 FROM journal_line reversed LEFT JOIN journal_line o ON o.tenant_id=reversed.tenant_id AND o.entity_id=reversed.entity_id AND o.journal_entry_id=p_original AND o.line_no=reversed.line_no WHERE reversed.tenant_id=p_tenant AND reversed.entity_id=p_entity AND reversed.journal_entry_id=p_journal AND(o.journal_line_id IS NULL OR reversed.account_code<>o.account_code OR reversed.member_ref IS DISTINCT FROM o.member_ref OR reversed.dimensions<>o.dimensions OR reversed.debit_amount<>o.credit_amount OR reversed.credit_amount<>o.debit_amount)) THEN RAISE EXCEPTION 'Reversal journal must remain an exact inverse of its Posted original' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM journal_line jl LEFT JOIN account_master a ON(a.tenant_id,a.entity_id,a.account_code)=(jl.tenant_id,jl.entity_id,jl.account_code) AND a.active LEFT JOIN member_master m ON(m.tenant_id,m.entity_id,m.member_ref)=(jl.tenant_id,jl.entity_id,jl.member_ref) AND m.active WHERE jl.tenant_id=p_tenant AND jl.entity_id=p_entity AND jl.journal_entry_id=p_journal AND(a.account_code IS NULL OR(a.requires_member AND jl.member_ref IS NULL) OR(jl.member_ref IS NOT NULL AND m.member_ref IS NULL) OR(a.requires_member AND NOT(m.member_type=a.required_member_type OR(a.required_member_type='CUSTOMER_OR_AFFILIATE' AND m.member_type IN('CUSTOMER','AFFILIATE')))))) THEN RAISE EXCEPTION 'Account/member validation failed' USING ERRCODE='23514';END IF;
 INSERT INTO posting_batch(posting_batch_id,tenant_id,entity_id,period_id,idempotency_key,request_hash,posted_by) VALUES(batch_id,p_tenant,p_entity,p_period,p_idempotency_key,p_request_hash,p_actor);
 INSERT INTO ledger_line(tenant_id,entity_id,period_id,posting_batch_id,journal_entry_id,journal_line_id,account_code,member_ref,currency,debit_amount,credit_amount,dimensions,posted_at) SELECT p_tenant,p_entity,p_period,batch_id,p_journal,journal_line_id,account_code,member_ref,je.currency,debit_amount,credit_amount,dimensions,clock_timestamp() FROM journal_line WHERE tenant_id=p_tenant AND entity_id=p_entity AND journal_entry_id=p_journal;
 INSERT INTO source_link(tenant_id,entity_id,link_type,journal_entry_id,journal_line_id,posting_batch_id,ledger_line_id,created_by) SELECT p_tenant,p_entity,'JE_LINE_TO_LEDGER',p_journal,ll.journal_line_id,batch_id,ll.ledger_line_id,p_actor FROM ledger_line ll WHERE tenant_id=p_tenant AND entity_id=p_entity AND posting_batch_id=batch_id;
 UPDATE journal_entry SET status='POSTED',posted_by=p_actor,posted_at=clock_timestamp(),revision=revision+1 WHERE tenant_id=p_tenant AND entity_id=p_entity AND journal_entry_id=p_journal AND revision=p_expected_revision;IF NOT FOUND THEN RAISE EXCEPTION 'Unit Transfer reversal Journal revision conflict' USING ERRCODE='40001';END IF;
 payload:=jsonb_build_object('journal_entry_id',p_journal,'posting_batch_id',batch_id,'idempotent',false);INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash) VALUES(p_tenant,p_entity,'JOURNAL_POSTED','JOURNAL_ENTRY',p_journal,'POST',p_actor,'USER','GL.JE.POST',p_idempotency_key,p_idempotency_key,p_idempotency_key,p_request_hash);INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'JOURNAL_ENTRY',p_journal,'JOURNAL_POSTED',payload,refs_jsonb_hash(payload));RETURN payload;END;$$;

CREATE FUNCTION refs_post_unit_transfer_reversal_pair(p_tenant uuid,p_entity uuid,p_original_pair_id uuid,p_reversal_pair_id uuid,p_expected_reversal_pair_revision bigint,p_expected_source_reversal_revision bigint,p_expected_target_reversal_revision bigint,p_idempotency_key text,p_request_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();idem idempotency_receipt;reversal_pair unit_transfer_reversal_pair;original_pair unit_transfer_pair;unit_control unit_transfer_unit_control;source_original_journal journal_entry;target_original_journal journal_entry;source_reversal_journal journal_entry;target_reversal_journal journal_entry;source_ic unit_transfer_ic_open_item;target_ic unit_transfer_ic_open_item;target_snapshot jsonb;target_ids uuid[];source_net numeric(20,4);source_result jsonb;target_result jsonb;h text;payload jsonb;elim unit_transfer_elimination_basis;elimination_reversal_id uuid;elimination_reversal_hash text;
BEGIN IF actor IS NULL OR p_request_hash IS DISTINCT FROM refs_unit_transfer_reversal_post_hash(p_tenant,p_entity,p_original_pair_id,p_reversal_pair_id,p_expected_reversal_pair_revision,p_expected_source_reversal_revision,p_expected_target_reversal_revision) OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 THEN RAISE EXCEPTION 'Invalid Unit Transfer reversal Post command' USING ERRCODE='22023';END IF;
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'UNIT_TRANSFER_REVERSAL_POST:'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='UNIT_TRANSFER_REVERSAL_POST:'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Unit Transfer reversal Post idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 SELECT * INTO reversal_pair FROM unit_transfer_reversal_pair WHERE tenant_id=p_tenant AND original_unit_transfer_pair_id=p_original_pair_id AND unit_transfer_reversal_pair_id=p_reversal_pair_id AND p_entity IN(source_entity_id,target_entity_id) FOR UPDATE;IF NOT FOUND OR reversal_pair.status<>'APPROVED_PAIR' OR reversal_pair.revision<>p_expected_reversal_pair_revision THEN RAISE EXCEPTION 'Unit Transfer reversal pair is not approved at expected revision' USING ERRCODE='40001';END IF;
 SELECT * INTO original_pair FROM unit_transfer_pair WHERE tenant_id=p_tenant AND unit_transfer_pair_id=reversal_pair.original_unit_transfer_pair_id FOR UPDATE;SELECT * INTO unit_control FROM unit_transfer_unit_control WHERE tenant_id=p_tenant AND unit_control_id=reversal_pair.unit_control_id FOR UPDATE;PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||unit_control.property_ref||':'||unit_control.unit_ref,0));
 SELECT * INTO source_original_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=original_pair.source_entity_id AND journal_entry_id=original_pair.source_journal_entry_id FOR UPDATE;SELECT * INTO target_original_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=original_pair.target_entity_id AND journal_entry_id=original_pair.target_journal_entry_id FOR UPDATE;SELECT * INTO source_reversal_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=original_pair.source_entity_id AND journal_entry_id=reversal_pair.source_reversal_journal_entry_id FOR UPDATE;SELECT * INTO target_reversal_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=original_pair.target_entity_id AND journal_entry_id=reversal_pair.target_reversal_journal_entry_id FOR UPDATE;
 IF original_pair.status<>'POSTED_PAIR' OR original_pair.revision<>reversal_pair.expected_original_pair_revision OR source_original_journal.revision<>reversal_pair.expected_source_original_revision OR target_original_journal.revision<>reversal_pair.expected_target_original_revision OR source_reversal_journal.revision<>p_expected_source_reversal_revision OR target_reversal_journal.revision<>p_expected_target_reversal_revision OR unit_control.version<>reversal_pair.expected_unit_version OR unit_control.last_transfer_pair_id IS DISTINCT FROM original_pair.unit_transfer_pair_id OR unit_control.last_transfer_reversal_id IS DISTINCT FROM reversal_pair.expected_prior_reversal_id THEN RAISE EXCEPTION 'Unit Transfer reversal aggregate revision conflict' USING ERRCODE='40001';END IF;
 PERFORM refs_assert_scope(p_tenant,original_pair.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVERSE');PERFORM refs_assert_scope(p_tenant,original_pair.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVERSE');PERFORM refs_assert_scope(p_tenant,original_pair.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.POST');PERFORM refs_assert_scope(p_tenant,original_pair.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.POST');PERFORM refs_assert_scope(p_tenant,original_pair.source_entity_id,'GL.JE.POST');PERFORM refs_assert_scope(p_tenant,original_pair.target_entity_id,'GL.JE.POST');
 IF actor IN(reversal_pair.created_by,source_reversal_journal.reviewed_by,source_reversal_journal.approved_by,target_reversal_journal.reviewed_by,target_reversal_journal.approved_by,source_original_journal.created_by,source_original_journal.reviewed_by,source_original_journal.approved_by,source_original_journal.posted_by,target_original_journal.created_by,target_original_journal.reviewed_by,target_original_journal.approved_by,target_original_journal.posted_by) THEN RAISE EXCEPTION 'Unit Transfer reversal Post SoD violation' USING ERRCODE='42501';END IF;
 target_snapshot:=refs_unit_transfer_reversal_target_cost_snapshot(p_tenant,original_pair,unit_control.property_ref,'9999-12-31'::date);target_ids:=ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(target_snapshot->'ledger_line_ids') value ORDER BY value::uuid);source_net:=refs_unit_transfer_reversal_source_net(p_tenant,original_pair,unit_control.property_ref,'9999-12-31'::date);
 IF target_snapshot IS NULL OR(target_snapshot->>'amount')::numeric<>original_pair.transfer_price OR target_ids IS DISTINCT FROM reversal_pair.target_cost_ledger_line_ids OR target_snapshot->>'basis_hash' IS DISTINCT FROM reversal_pair.target_cost_basis_hash THEN RAISE EXCEPTION 'Target Unit Transfer cost moved after Post' USING ERRCODE='55000';END IF;IF source_net<>0 THEN RAISE EXCEPTION 'Source Unit Transfer cost is not zero after Post' USING ERRCODE='55000';END IF;
 SELECT * INTO source_ic FROM unit_transfer_ic_open_item WHERE tenant_id=p_tenant AND unit_transfer_ic_open_item_id=reversal_pair.source_ic_open_item_id FOR UPDATE;SELECT * INTO target_ic FROM unit_transfer_ic_open_item WHERE tenant_id=p_tenant AND unit_transfer_ic_open_item_id=reversal_pair.target_ic_open_item_id FOR UPDATE;IF source_ic.version<>reversal_pair.expected_source_ic_version OR target_ic.version<>reversal_pair.expected_target_ic_version OR source_ic.status<>'OPEN' OR target_ic.status<>'OPEN' OR source_ic.remaining_amount<>original_pair.transfer_price OR target_ic.remaining_amount<>original_pair.transfer_price OR source_ic.journal_entry_id<>original_pair.source_journal_entry_id OR target_ic.journal_entry_id<>original_pair.target_journal_entry_id OR source_ic.account_code<>original_pair.source_due_from_account_code OR target_ic.account_code<>original_pair.target_due_to_account_code THEN RAISE EXCEPTION 'Unit Transfer IC open items changed before reversal Post' USING ERRCODE='40001';END IF;IF refs_unit_transfer_ic_has_later_activity(p_tenant,source_ic,target_ic) THEN RAISE EXCEPTION 'Unit Transfer IC accounts have later Posted activity that may represent settlement' USING ERRCODE='55000';END IF;
 IF reversal_pair.source_reversal_journal_snapshot_hash<>refs_unit_transfer_journal_snapshot(p_tenant,original_pair.source_entity_id,reversal_pair.source_reversal_journal_entry_id) OR reversal_pair.target_reversal_journal_snapshot_hash<>refs_unit_transfer_journal_snapshot(p_tenant,original_pair.target_entity_id,reversal_pair.target_reversal_journal_entry_id) THEN RAISE EXCEPTION 'Unit Transfer reversal financial lines changed' USING ERRCODE='23514';END IF;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_reversal_pair_id,'HEADER',reversal_pair.source_reversal_journal_entry_id,'BIND_REVERSAL');UPDATE journal_entry SET reversal_of_id=original_pair.source_journal_entry_id WHERE tenant_id=p_tenant AND entity_id=original_pair.source_entity_id AND journal_entry_id=reversal_pair.source_reversal_journal_entry_id AND revision=p_expected_source_reversal_revision;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_reversal_pair_id,'HEADER',reversal_pair.target_reversal_journal_entry_id,'BIND_REVERSAL');UPDATE journal_entry SET reversal_of_id=original_pair.target_journal_entry_id WHERE tenant_id=p_tenant AND entity_id=original_pair.target_entity_id AND journal_entry_id=reversal_pair.target_reversal_journal_entry_id AND revision=p_expected_target_reversal_revision;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_reversal_pair_id,'JOURNAL',reversal_pair.source_reversal_journal_entry_id,'POSTED');h:=refs_jsonb_hash(jsonb_build_object('tenantId',p_tenant,'entityId',original_pair.source_entity_id,'journalEntryId',reversal_pair.source_reversal_journal_entry_id,'expectedRevision',p_expected_source_reversal_revision));source_result:=refs_post_unit_transfer_reversal_journal(p_tenant,original_pair.source_entity_id,reversal_pair.source_period_id,p_reversal_pair_id,reversal_pair.source_reversal_journal_entry_id,original_pair.source_journal_entry_id,p_expected_source_reversal_revision,'unit-transfer-reversal:'||p_reversal_pair_id||':source:'||p_idempotency_key,h,actor);
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_reversal_pair_id,'JOURNAL',reversal_pair.target_reversal_journal_entry_id,'POSTED');h:=refs_jsonb_hash(jsonb_build_object('tenantId',p_tenant,'entityId',original_pair.target_entity_id,'journalEntryId',reversal_pair.target_reversal_journal_entry_id,'expectedRevision',p_expected_target_reversal_revision));target_result:=refs_post_unit_transfer_reversal_journal(p_tenant,original_pair.target_entity_id,reversal_pair.target_period_id,p_reversal_pair_id,reversal_pair.target_reversal_journal_entry_id,original_pair.target_journal_entry_id,p_expected_target_reversal_revision,'unit-transfer-reversal:'||p_reversal_pair_id||':target:'||p_idempotency_key,h,actor);
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,original_pair.unit_transfer_pair_id,'IC_OPEN_ITEM',source_ic.journal_entry_id,'SETTLED');UPDATE unit_transfer_ic_open_item SET status='SETTLED',remaining_amount=0,version=version+1,settled_by_journal_entry_id=reversal_pair.source_reversal_journal_entry_id,settlement_evidence_hash=refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_IC_SETTLEMENT_V1','unit_transfer_reversal_pair_id',p_reversal_pair_id,'unit_transfer_ic_open_item_id',source_ic.unit_transfer_ic_open_item_id,'reversal_journal_entry_id',reversal_pair.source_reversal_journal_entry_id)),updated_at=clock_timestamp() WHERE tenant_id=p_tenant AND unit_transfer_ic_open_item_id=source_ic.unit_transfer_ic_open_item_id AND version=reversal_pair.expected_source_ic_version AND status='OPEN';IF NOT FOUND THEN RAISE EXCEPTION 'Source Unit Transfer IC open item changed' USING ERRCODE='40001';END IF;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,original_pair.unit_transfer_pair_id,'IC_OPEN_ITEM',target_ic.journal_entry_id,'SETTLED');UPDATE unit_transfer_ic_open_item SET status='SETTLED',remaining_amount=0,version=version+1,settled_by_journal_entry_id=reversal_pair.target_reversal_journal_entry_id,settlement_evidence_hash=refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_IC_SETTLEMENT_V1','unit_transfer_reversal_pair_id',p_reversal_pair_id,'unit_transfer_ic_open_item_id',target_ic.unit_transfer_ic_open_item_id,'reversal_journal_entry_id',reversal_pair.target_reversal_journal_entry_id)),updated_at=clock_timestamp() WHERE tenant_id=p_tenant AND unit_transfer_ic_open_item_id=target_ic.unit_transfer_ic_open_item_id AND version=reversal_pair.expected_target_ic_version AND status='OPEN';IF NOT FOUND THEN RAISE EXCEPTION 'Target Unit Transfer IC open item changed' USING ERRCODE='40001';END IF;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_reversal_pair_id,'UNIT',unit_control.unit_control_id,'REVERSED');UPDATE unit_transfer_unit_control SET current_owner_entity_id=original_pair.source_entity_id,current_asset_account_codes=original_pair.source_carrying_account_codes,lifecycle_stage=original_pair.source_lifecycle_stage,version=version+1,last_transfer_reversal_id=p_reversal_pair_id,updated_at=clock_timestamp() WHERE tenant_id=p_tenant AND unit_control_id=unit_control.unit_control_id AND version=reversal_pair.expected_unit_version AND current_owner_entity_id=original_pair.target_entity_id AND last_transfer_pair_id=original_pair.unit_transfer_pair_id;IF NOT FOUND THEN RAISE EXCEPTION 'Unit ownership changed before reversal Post' USING ERRCODE='40001';END IF;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_reversal_pair_id,'PAIR',p_reversal_pair_id,'POSTED_PAIR');UPDATE unit_transfer_reversal_pair SET status='POSTED_PAIR',revision=revision+1,completed_at=clock_timestamp() WHERE tenant_id=p_tenant AND unit_transfer_reversal_pair_id=p_reversal_pair_id;
 SELECT * INTO elim FROM unit_transfer_elimination_basis WHERE tenant_id=p_tenant AND unit_transfer_pair_id=original_pair.unit_transfer_pair_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Original Unit Transfer elimination basis is missing' USING ERRCODE='23514';END IF;
 elimination_reversal_hash:=refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_ELIMINATION_REVERSAL_BASIS_V1','unit_transfer_reversal_pair_id',p_reversal_pair_id,'original_elimination_basis_id',elim.elimination_basis_id,'signed_elimination_amount',-elim.intercompany_profit));
 INSERT INTO unit_transfer_elimination_reversal_basis(tenant_id,unit_transfer_reversal_pair_id,original_elimination_basis_id,source_entity_id,target_entity_id,currency,original_intercompany_profit,signed_elimination_amount,source_reversal_journal_entry_id,target_reversal_journal_entry_id,evidence_hash) VALUES(p_tenant,p_reversal_pair_id,elim.elimination_basis_id,original_pair.source_entity_id,original_pair.target_entity_id,original_pair.currency,elim.intercompany_profit,-elim.intercompany_profit,reversal_pair.source_reversal_journal_entry_id,reversal_pair.target_reversal_journal_entry_id,elimination_reversal_hash) RETURNING elimination_reversal_basis_id,evidence_hash INTO elimination_reversal_id,elimination_reversal_hash;
 payload:=jsonb_build_object('schema_version','UNIT_TRANSFER_REVERSAL_POST_RECEIPT_V1','unit_transfer_reversal_pair_id',p_reversal_pair_id,'original_unit_transfer_pair_id',original_pair.unit_transfer_pair_id,'unit_control_id',unit_control.unit_control_id,'unit_version',reversal_pair.expected_unit_version+1,'status','POSTED_PAIR','revision',reversal_pair.revision+1,'source_journal',source_result,'target_journal',target_result,'elimination_reversal_basis_id',elimination_reversal_id,'evidence_hash',elimination_reversal_hash,'idempotent',false);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,metadata) VALUES(p_tenant,original_pair.source_entity_id,'UNIT_TRANSFER_REVERSAL_POSTED','UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair_id,'POST',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.REVERSE',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),payload),(p_tenant,original_pair.target_entity_id,'UNIT_TRANSFER_REVERSAL_POSTED','UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair_id,'POST',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.REVERSE',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,original_pair.source_entity_id,'UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair_id,'UNIT_TRANSFER_REVERSAL_POSTED',payload,refs_jsonb_hash(payload)),(p_tenant,original_pair.target_entity_id,'UNIT_TRANSFER_REVERSAL_PAIR',p_reversal_pair_id,'UNIT_TRANSFER_REVERSAL_POSTED',payload,refs_jsonb_hash(payload));UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;
END;$$;

CREATE FUNCTION refs_read_unit_transfer_reversal_pair(p_tenant uuid,p_entity uuid,p_original_pair uuid,p_reversal_pair uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();r unit_transfer_reversal_pair;source_journal journal_entry;target_journal journal_entry;elim jsonb;
BEGIN SELECT * INTO r FROM unit_transfer_reversal_pair WHERE tenant_id=p_tenant AND original_unit_transfer_pair_id=p_original_pair AND unit_transfer_reversal_pair_id=p_reversal_pair AND p_entity IN(source_entity_id,target_entity_id);IF NOT FOUND THEN RAISE EXCEPTION 'Unit Transfer reversal pair not found' USING ERRCODE='P0002';END IF;
 PERFORM refs_assert_scope(p_tenant,r.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.VIEW');PERFORM refs_assert_scope(p_tenant,r.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.VIEW');PERFORM refs_assert_scope(p_tenant,r.source_entity_id,'GL.JE.VIEW');PERFORM refs_assert_scope(p_tenant,r.target_entity_id,'GL.JE.VIEW');
 SELECT * INTO source_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=r.source_entity_id AND journal_entry_id=r.source_reversal_journal_entry_id;SELECT * INTO target_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=r.target_entity_id AND journal_entry_id=r.target_reversal_journal_entry_id;
 SELECT jsonb_build_object('elimination_reversal_basis_id',elimination_reversal_basis_id,'original_elimination_basis_id',original_elimination_basis_id,'evidence_hash',evidence_hash) INTO elim FROM unit_transfer_elimination_reversal_basis WHERE tenant_id=p_tenant AND unit_transfer_reversal_pair_id=p_reversal_pair;
 RETURN jsonb_build_object('unit_transfer_reversal_pair_id',r.unit_transfer_reversal_pair_id,'source_period_id',r.source_period_id,'target_period_id',r.target_period_id,'reversal_date',r.reversal_date,'source_journal_entry_id',r.source_reversal_journal_entry_id,'source_journal_status',source_journal.status::text,'source_journal_revision',source_journal.revision::text,'target_journal_entry_id',r.target_reversal_journal_entry_id,'target_journal_status',target_journal.status::text,'target_journal_revision',target_journal.revision::text,'status',r.status,'revision',r.revision::text,'evidence_hash',r.evidence_hash,'created_by',r.created_by,'created_at',r.created_at,'completed_at',r.completed_at,'cancelled_by',r.cancelled_by,'cancelled_at',r.cancelled_at,'cancel_reason',r.cancel_reason,'elimination_reversal_basis',elim,'action_flags',jsonb_build_object('can_create_draft',false,'can_submit',r.status='DRAFT_PAIR' AND refs_entity_has_permission(r.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.SUBMIT') AND refs_entity_has_permission(r.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.SUBMIT'),'can_review',r.status='PENDING_REVIEW_PAIR' AND actor IS DISTINCT FROM r.created_by AND refs_entity_has_permission(r.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVIEW') AND refs_entity_has_permission(r.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVIEW'),'can_approve',r.status='PENDING_APPROVAL_PAIR' AND actor IS DISTINCT FROM r.created_by AND actor IS DISTINCT FROM source_journal.reviewed_by AND actor IS DISTINCT FROM target_journal.reviewed_by AND refs_entity_has_permission(r.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.APPROVE') AND refs_entity_has_permission(r.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.APPROVE'),'can_reject',r.status IN('PENDING_REVIEW_PAIR','PENDING_APPROVAL_PAIR') AND actor IS DISTINCT FROM r.created_by,'can_cancel',r.status='DRAFT_PAIR' AND actor IS DISTINCT FROM r.created_by,'can_post',r.status='APPROVED_PAIR' AND actor IS DISTINCT FROM r.created_by AND actor IS DISTINCT FROM source_journal.reviewed_by AND actor IS DISTINCT FROM source_journal.approved_by AND actor IS DISTINCT FROM target_journal.reviewed_by AND actor IS DISTINCT FROM target_journal.approved_by,'can_reverse',false));
END;$$;

CREATE FUNCTION refs_unit_transfer_can_reverse(p_tenant uuid,p_pair unit_transfer_pair,p_unit unit_transfer_unit_control) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();source_original_journal journal_entry;target_original_journal journal_entry;source_ic unit_transfer_ic_open_item;target_ic unit_transfer_ic_open_item;snapshot jsonb;ids uuid[];expected_ids uuid[];
BEGIN IF actor IS NULL OR p_pair.status<>'POSTED_PAIR' OR p_unit.last_transfer_pair_id IS DISTINCT FROM p_pair.unit_transfer_pair_id OR p_unit.current_owner_entity_id<>p_pair.target_entity_id OR EXISTS(SELECT 1 FROM unit_transfer_reversal_pair r WHERE r.tenant_id=p_tenant AND r.original_unit_transfer_pair_id=p_pair.unit_transfer_pair_id AND r.status<>'CANCELLED_PAIR') OR NOT refs_entity_has_permission(p_pair.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVERSE') OR NOT refs_entity_has_permission(p_pair.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVERSE') OR NOT refs_entity_has_permission(p_pair.source_entity_id,'GL.JE.REVERSE') OR NOT refs_entity_has_permission(p_pair.target_entity_id,'GL.JE.REVERSE') THEN RETURN false;END IF;
 SELECT * INTO source_original_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=p_pair.source_entity_id AND journal_entry_id=p_pair.source_journal_entry_id;
 SELECT * INTO target_original_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=p_pair.target_entity_id AND journal_entry_id=p_pair.target_journal_entry_id;
 IF source_original_journal.journal_entry_id IS NULL OR target_original_journal.journal_entry_id IS NULL OR actor IN(p_pair.created_by,source_original_journal.created_by,source_original_journal.reviewed_by,source_original_journal.approved_by,source_original_journal.posted_by,target_original_journal.created_by,target_original_journal.reviewed_by,target_original_journal.approved_by,target_original_journal.posted_by) THEN RETURN false;END IF;
 SELECT * INTO source_ic FROM unit_transfer_ic_open_item WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair.unit_transfer_pair_id AND entity_id=p_pair.source_entity_id AND direction='DUE_FROM';SELECT * INTO target_ic FROM unit_transfer_ic_open_item WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair.unit_transfer_pair_id AND entity_id=p_pair.target_entity_id AND direction='DUE_TO';IF source_ic.unit_transfer_ic_open_item_id IS NULL OR target_ic.unit_transfer_ic_open_item_id IS NULL OR source_ic.status<>'OPEN' OR target_ic.status<>'OPEN' OR source_ic.remaining_amount<>p_pair.transfer_price OR target_ic.remaining_amount<>p_pair.transfer_price OR refs_unit_transfer_ic_has_later_activity(p_tenant,source_ic,target_ic) THEN RETURN false;END IF;
 snapshot:=refs_unit_transfer_reversal_target_cost_snapshot(p_tenant,p_pair,p_unit.property_ref,'9999-12-31'::date);ids:=ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(snapshot->'ledger_line_ids') value ORDER BY value::uuid);SELECT array_agg(l.ledger_line_id ORDER BY l.ledger_line_id) INTO expected_ids FROM ledger_line l WHERE l.tenant_id=p_tenant AND l.entity_id=p_pair.target_entity_id AND l.journal_entry_id=p_pair.target_journal_entry_id AND l.account_code=p_pair.target_inventory_account_code AND l.dimensions->>'property_ref'=p_unit.property_ref AND l.dimensions->>'unit_ref'=p_pair.unit_ref;RETURN snapshot IS NOT NULL AND(snapshot->>'amount')::numeric=p_pair.transfer_price AND ids IS NOT DISTINCT FROM expected_ids AND refs_unit_transfer_reversal_source_net(p_tenant,p_pair,p_unit.property_ref,'9999-12-31'::date)=0;
END;$$;

DO $unit_transfer_read_patch$
DECLARE fn text; patched text;
BEGIN
 fn:=pg_get_functiondef('refs_read_unit_transfer_pair(uuid,uuid,uuid)'::regprocedure);
 patched:=replace(fn,'public.refs_read_unit_transfer_pair(','public.refs_read_unit_transfer_pair_370(');
 IF patched=fn THEN RAISE EXCEPTION 'Unable to retain 370 Unit Transfer read function' USING ERRCODE='55000'; END IF;
 BEGIN EXECUTE patched||';'; EXCEPTION WHEN syntax_error THEN RAISE EXCEPTION 'Unit Transfer migration read backup definition is invalid' USING ERRCODE='42601'; END;
 patched:=replace(fn,$needle$'elimination_basis',elimination,'created_by'$needle$,$replacement$'elimination_basis',elimination,'reversal_history',COALESCE((SELECT jsonb_agg(refs_read_unit_transfer_reversal_pair(p_tenant,p_entity,p.unit_transfer_pair_id,r.unit_transfer_reversal_pair_id) ORDER BY r.created_at,r.unit_transfer_reversal_pair_id) FROM unit_transfer_reversal_pair r WHERE r.tenant_id=p_tenant AND r.original_unit_transfer_pair_id=p.unit_transfer_pair_id),'[]'::jsonb),'active_reversal',(SELECT refs_read_unit_transfer_reversal_pair(p_tenant,p_entity,p.unit_transfer_pair_id,r.unit_transfer_reversal_pair_id) FROM unit_transfer_reversal_pair r WHERE r.tenant_id=p_tenant AND r.original_unit_transfer_pair_id=p.unit_transfer_pair_id AND r.status NOT IN('POSTED_PAIR','CANCELLED_PAIR') ORDER BY r.created_at DESC,r.unit_transfer_reversal_pair_id DESC LIMIT 1),'created_by'$replacement$);
 patched:=replace(patched,$needle$'can_post',p.status='APPROVED_PAIR'$needle$,$replacement$'can_reverse',refs_unit_transfer_can_reverse(p_tenant,p,u),'can_post',p.status='APPROVED_PAIR'$replacement$);
 IF patched=fn THEN RAISE EXCEPTION 'Unable to extend Unit Transfer read with paired reversal' USING ERRCODE='55000'; END IF;
 BEGIN EXECUTE patched||';'; EXCEPTION WHEN syntax_error THEN RAISE EXCEPTION 'Unit Transfer migration read extension definition is invalid' USING ERRCODE='42601'; END;
END;
$unit_transfer_read_patch$;
REVOKE ALL ON FUNCTION refs_read_unit_transfer_pair_370(uuid,uuid,uuid) FROM PUBLIC,refs_app;

